public function getList(array $where, string $field = '*', int $page = 0, int $limit = 0, string $order = 'start_time asc,id desc')
{
    return $this->search($where)->field($field)
        ->when($page != 0 && $limit != 0, function ($query) use ($page, $limit) {
            $query->page($page, $limit);
        })->order($order)->select()->toArray();
}

    public function getListByTime(int $time)
    {
		[$page, $limit] = $this->getPageValue();
		/** @var StoreActivityServices $storeActivityServices */
		$storeActivityServices = app()->make(StoreActivityServices::class);
		$activityList = $storeActivityServices->getList(['time_id' => $time, 'type' => 1, 'status' => 1, 'is_del' => 0, 'activityTime' => true], 'id,image');
		$seckillInfo = [];
		if ($activityList) {
			$activityIds = array_column($activityList, 'id');
			$field = 'id,product_id,activity_id,title,image,price,ot_price,quota,quota_show,freight,stock,store_label_id';
			$seckillInfo = $this->dao->getListByTime($activityIds, [], $field, $page, $limit);
			if (count($seckillInfo)) {
				$activityList = array_combine($activityIds, $activityList);
				/** @var StoreProductLabelServices $storeProductLabelServices */
            	$storeProductLabelServices = app()->make(StoreProductLabelServices::class);
				foreach ($seckillInfo as $key => &$item) {
					if ($item['quota'] > 0) {
						$percent =  (float)sprintf("%.1f", (($item['quota_show'] - $item['quota']) / $item['quota_show'] * 100));
						$item['percent'] = $percent;
						$item['stock'] = $item['quota'];
					} else {
						$item['percent'] = 100;
						$item['stock'] = 0;
					}
					$item['price'] = floatval($item['price']);
					$item['ot_price'] = floatval($item['ot_price']);
					$item['discount_num'] = $item['ot_price'] ? (float)bcmul(bcdiv((string)$item['price'], (string)$item['ot_price'], 4), '10', 1) : 10;
					$item['activity_image'] = $activityList[$item['activity_id']]['image'] ?? '';
					$item['store_label'] = [];
					if ($item['store_label_id']) {
						$item['store_label'] = $storeProductLabelServices->getLabelCache($item['store_label_id'], ['id', 'label_name', 'style_type', 'color', 'bg_color', 'border_color', 'icon']);
					}
                    /** @var StoreProductServices $storeProductServices */
                    $storeProductServices = app()->make(StoreProductServices::class);
                    $item['brand_name'] = $storeProductServices->productIdByBrandName((int)$item['product_id']);
				}
			}
		}

        return $seckillInfo;

    public function getListByTime(array $activity_id, array $ids = [], string $field = '*', int $page = 0, int $limit = 0, bool $isStore = false)
    {
        if ($activity_id == 0) return [];
        return $this->search(['is_del' => 0, 'status' => 1])->field($field)
            ->where('start_time', '<=', time())
            ->where('stop_time', '>=', time() - 86400)
            ->when($activity_id, function ($query) use ($activity_id) {
                $query->whereIn('activity_id', $activity_id);
            })->where('product_id', 'IN', function ($query) {
                $query->name('store_product')->where('is_del', 0)->field('id');
            })->when($ids, function($query) use($ids) {
                $query->whereIn('product_id', $ids);
            })->when($isStore, function($query) {
                $query->where(function ($q) {
					$q->whereOr(function ($c) {
                            $c->whereFindInSet('delivery_type', 2);
                        })->whereOr(function ($d) {
                            $d->whereFindInSet('delivery_type', 3);
                        });
                });
            })->when($page && $limit, function ($query) use ($page, $limit) {
                $query->page($page, $limit);
            })->when(!$page && $limit, function ($query) use ($limit) {
                $query->limit($limit);
            })->order('sort desc,id desc')->select()->toArray();
    }

public function search(array $where = [], bool $search = true)
{
	return parent::search($where)->when(isset($where['activityTime']), function ($query) use ($where) {
		[$startTime, $stopTime] = is_array($where['activityTime']) ? $where['activityTime'] : [time(), time() - 86400];
		$query->where('start_day', '<=', $startTime)->where('end_day', '>=', $stopTime);
	})->when(isset($where['start_status']) && $where['start_status'] !== '', function ($query) use ($where) {
		$time = time();
		switch ($where['start_status']) {
			case -1:
				$query->where(function ($q) use ($time) {
					$q->where('end_day', '<', $time - 86400)->whereOr('status', '0');
				});
				break;
			case 0:
				$query->where('start_day', '>', $time)->where('status', 1);
				break;
			case 1:
				$query->where('start_day', '<=', $time)->where('end_day', '>=', $time - 86400)->where('status', 1);
				break;
		}
	});

		}
	}

