const editor=path.join(root,'components/content/DiySeckillEditor.vue'),preview=path.join(root,'components/content/DiySeckillPreview.vue'),util=path.join(root,'utils/diySeckillEditor.ts');
const fresh=(time=10)=>loader().load(util).newSeckillBlock(time);
const product=(id=17,extra={})=>({id,product_id:id+1000,activity_id:9,activity_image:'/activities/frame.png',percent:50,title:'当前秒杀商品'+id,people:3,sales:9,image:'/products/'+id+'.png',price:'7.00',ot_price:'12.00',sales:9,stock:99,...extra});
const schedule=()=>({seckillTime:[{id:4,start_time:'00:00',end_time:'24:00',state:'疯抢中',stop:0,status:1}],seckillTimeIndex:0});
const response=(data,status=200)=>({ok:status===200,status,json:async()=>({status:status===200?200:400000,msg:'秒杀商品读取失败',data})});
function harness(value=[fresh()],options={}){const l=loader(options),props=vue.reactive({modelValue:JSON.stringify(value),editorKey:'seckill:2',pageId:2,disabled:false,...options.props}),writes=[],m=mount(l,editor,props,(_n,raw)=>{writes.push(raw);props.modelValue=raw;});return{...l,...m,props,writes,value:()=>JSON.parse(props.modelValue)};}
function control(r,label){const f=all(r.tree,n=>n.props['data-element']==='el-form-item'&&n.props['data-label']===label)[0];assert.ok(f,label);const c=all(f,n=>['el-select','el-input','el-input-number','el-switch'].includes(n.props['data-element'])&&n.props['onUpdate:modelValue'])[0];assert.ok(c,label);return c;}
