async function fetches(send,work){const previous=global.fetch;global.fetch=(url,init)=>{if(url==='/api/seckill/index'){assert.equal(init.method,'GET');assert.equal(init.credentials,'omit');assert.equal(init.cache,'no-store');assert.deepEqual(init.headers,{Accept:'application/json'});return Promise.resolve(response(schedule()));}return send(url,init);};try{await work();}finally{global.fetch=previous;}}
