async function cross(r,boundary,raw,aba=false){if(boundary==='component'){r.state.select(1);await tick();if(aba)r.state.select(0);}if(boundary==='raw'){r.props.modelValue=JSON.stringify([{...r.value()[0],external:true},fresh(20)]);await tick();if(aba)r.props.modelValue=raw;}if(boundary==='page'){r.props.pageId=9;await tick();if(aba)r.props.pageId=2;}if(boundary==='published'){r.props.pagePublished=true;await tick();if(aba)r.props.pagePublished=false;}if(boundary==='actor'){r.actor.token='B';r.storage.set('admin_token','B');r.window.dispatchEvent(new Event('admin-session-changed'));await tick();if(aba){r.actor.token='A';r.storage.set('admin_token','A');}}if(boundary==='stored'){r.storage.set('admin_session','B');r.window.dispatchEvent(new Event('storage'));if(aba){r.storage.set('admin_session','session-A');r.window.dispatchEvent(new Event('storage'));}}if(boundary==='disabled'){r.props.disabled=true;await tick();if(aba)r.props.disabled=false;}if(boundary==='unmount')r.unmount();await tick();}
